import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class MutableDateTime_addYears_TriageGen1Test {

    @Test
    public void testAddYears_Positive() {
        // Initialize with a specific date: 2020-01-01
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(5);
        assertEquals(2025, dt.getYear());
        assertEquals(1, dt.getMonthOfYear());
        assertEquals(1, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_Negative() {
        // Initialize with a specific date: 2020-01-01
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(-5);
        assertEquals(2015, dt.getYear());
    }

    @Test
    public void testAddYears_Zero() {
        // This covers the case where years == 0 (the 'if' condition fails)
        MutableDateTime dt = new MutableDateTime(2020, 1, 1, 0, 0, 0, 0);
        dt.addYears(0);
        assertEquals(2020, dt.getYear());
    }

    @Test
    public void testAddYears_LeapYearTransition() {
        // Testing leap year edge case: Feb 29th
        MutableDateTime dt = new MutableDateTime(2020, 2, 29, 0, 0, 0, 0);
        // Adding 1 year should result in Feb 28th in a non-leap year
        dt.addYears(1);
        assertEquals(2021, dt.getYear());
        assertEquals(2, dt.getMonthOfYear());
        assertEquals(28, dt.getDayOfMonth());
    }

    @Test
    public void testAddYears_LargeValue() {
        MutableDateTime dt = new MutableDateTime(1000, 1, 1, 0, 0, 0, 0);
        dt.addYears(8000);
        assertEquals(9000, dt.getYear());
    }
}
